package io.joshuasalcedo.swaswa.ui.markdown;

import io.joshuasalcedo.swaswa.html.Node;
import io.joshuasalcedo.swaswa.html.PageScript;
import io.joshuasalcedo.swaswa.html.Text;
import io.joshuasalcedo.swaswa.react.ReactElement;
import io.joshuasalcedo.swaswa.ui.Ui;
import java.util.List;
import java.util.function.Consumer;

/**
 * swaswa-ui's {@code Markdown} (markdown.tsx), a real React component, from Java: create it, set it, add it.
 * Generated by swaswa-react java-gen from its TypeScript props: do not edit.
 */
public final class UiMarkdown extends ReactElement<UiMarkdown> {

    /** A UiMarkdown. */
    public UiMarkdown() {
        super("Markdown", true);
    }

    /** A UiMarkdown showing {@code text}. */
    public UiMarkdown(String text) {
        this();
        add(new Text(text));
    }

    /** A UiMarkdown holding {@code children}: its children, where it shows them. */
    public UiMarkdown(Node... children) {
        this();
        for (Node child : children) add(child);
    }

    /** Told when it calls {@code onLink}, with what it calls it with. A link was clicked: where it goes. Without, it opens in a new tab (the system browser in a desktop window). */
    public UiMarkdown onLink(Consumer<String> listener) {
        return onEvent("onLink", e -> listener.accept(e.payload(String.class)));
    }

    /** {@code headingOffset}. Headings start at this level (2: a "# Title" is shown as an h2), for Markdown inside a page with its own title. */
    public UiMarkdown setHeadingOffset(double value) {
        return prop("headingOffset", value);
    }

    public Double getHeadingOffset() {
        return getProp("headingOffset", Double.class);
    }

    @Override
    protected List<PageScript> libraries() {
        return List.of(Ui.bundle());
    }
}
